import React, { forwardRef } from 'react';

// ---------------------------------------------------------------------------
// Shared types
// ---------------------------------------------------------------------------

interface BaseFormLabelProps {
  children: React.ReactNode;
  size?: 'sm' | 'lg';
  isRequired?: boolean;
  isDisabled?: boolean;
  isInvalid?: boolean;
  /** Custom node rendered in place of the default `*` required indicator. */
  requiredIndicator?: React.ReactNode;
}

function buildLabelClassName(
  base: string | undefined,
  size: 'sm' | 'lg',
  isRequired: boolean,
  isDisabled: boolean,
  isInvalid: boolean,
): string {
  return [
    'arvo-form-lbl',
    size === 'sm' && 'arvo-form-lbl--sm',
    isRequired && 'arvo-form-lbl--required',
    isDisabled && 'is-disabled',
    isInvalid && 'is-invalid',
    base,
  ]
    .filter(Boolean)
    .join(' ');
}

function renderRequiredIndicator(
  isRequired: boolean,
  custom: React.ReactNode | undefined,
): React.ReactNode {
  if (!isRequired) return null;
  if (custom !== undefined) return custom;
  return (
    <span className="arvo-form-lbl__req" aria-hidden="true">
      *
    </span>
  );
}

// ---------------------------------------------------------------------------
// ArvoFormLabel (renders <label>)
// ---------------------------------------------------------------------------

export interface ArvoFormLabelProps
  extends BaseFormLabelProps,
    Omit<React.LabelHTMLAttributes<HTMLLabelElement>, 'children'> {}

export const ArvoFormLabel = forwardRef<HTMLLabelElement, ArvoFormLabelProps>(
  function ArvoFormLabel(
    {
      children,
      size = 'lg',
      isRequired = false,
      isDisabled = false,
      isInvalid = false,
      requiredIndicator,
      className,
      ...rest
    },
    ref,
  ) {
    return (
      <label
        ref={ref}
        className={buildLabelClassName(className, size, isRequired, isDisabled, isInvalid)}
        {...rest}
      >
        {children}
        {renderRequiredIndicator(isRequired, requiredIndicator)}
      </label>
    );
  },
);

// ---------------------------------------------------------------------------
// ArvoFormLabelText (renders <span> for nested-inside-<label> use)
// ---------------------------------------------------------------------------

export interface ArvoFormLabelTextProps
  extends BaseFormLabelProps,
    Omit<React.HTMLAttributes<HTMLSpanElement>, 'children'> {}

export const ArvoFormLabelText = forwardRef<HTMLSpanElement, ArvoFormLabelTextProps>(
  function ArvoFormLabelText(
    {
      children,
      size = 'lg',
      isRequired = false,
      isDisabled = false,
      isInvalid = false,
      requiredIndicator,
      className,
      ...rest
    },
    ref,
  ) {
    return (
      <span
        ref={ref}
        className={buildLabelClassName(className, size, isRequired, isDisabled, isInvalid)}
        {...rest}
      >
        {children}
        {renderRequiredIndicator(isRequired, requiredIndicator)}
      </span>
    );
  },
);

// ---------------------------------------------------------------------------
// Internal aliases (deep-import compatibility for existing consumers)
// ---------------------------------------------------------------------------

export const FormLabel = ArvoFormLabel;
export const FormLabelText = ArvoFormLabelText;
